func TestEnumGetStockSplitsByIDRequestOrder(t *testing.T) {
	t.Run("NewFromString_asc", func(t *testing.T) {
		t.Parallel()
		val, err := NewGetStockSplitsByIDRequestOrderFromString("asc")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, GetStockSplitsByIDRequestOrder("asc"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_desc", func(t *testing.T) {
		t.Parallel()
		val, err := NewGetStockSplitsByIDRequestOrderFromString("desc")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, GetStockSplitsByIDRequestOrder("desc"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewGetStockSplitsByIDRequestOrderFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewGetStockSplitsByIDRequestOrderFromString("asc")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

